'QZ_Setup_Title' => 'Så här konfigurerar du utskrift via QZ Tray (en gång, på varje dator som skriver ut etiketter)',
'QZ_Step_Install' => '1. Installera QZ Tray på denna dator — ladda ner det gratis från qz.io, starta det och låt det köras (det ligger i systemfältet i Windows eller i menyraden i macOS).',
'QZ_Step_Connect' => '2. Anslut etikettskrivaren via USB och kontrollera att den är installerad i operativsystemet (Windows: Inställningar > Skrivare och skannrar — macOS: Systeminställningar > Skrivare och skannrar).',
'QZ_Step_Detect' => '3. Klicka på knappen ⟳ bredvid ”Skrivarnamn” ovan för att identifiera skrivarna på denna dator och välj sedan din etikettskrivare. Lämna fältet tomt för att använda datorns standardskrivare.',
'QZ_Step_Cert' => '4. För utskrift utan behörighetsfråga, ladda ner certifikatet nedan och kopiera det till installationsmappen för QZ Tray, omdöpt till override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Avsluta sedan QZ Tray och starta det igen.',
'QZ_Step_Test' => '5. Klicka på ”Skriv ut testetikett” nedan. Om QZ Tray ber om behörighet, klicka på Tillåt — med certifikatet installerat frågar det inte igen.',
'QZ_Step_Save' => '6. Klicka på Skicka för att spara inställningarna. Etiketter från sidan Skriv ut streckkod skrivs nu ut direkt på denna skrivare, utan webbläsarens utskriftsdialog.',
'QZ_Setup_Note' => 'QZ Tray körs på datorn du surfar från, så detta fungerar även när Stocky ligger på en fjärrserver. Varje dator som skriver ut etiketter behöver QZ Tray installerat.',
