'Upd_Guide_Code_Overwritten' => 'Om du har ändrat applikationens kod manuellt skrivs dina ändringar över av uppdateringen. Din data, uppladdningar, inställningar och .env bevaras alltid.',
'Upd_Guide_Running_Title' => '2. Köra uppdateringen',
'Upd_Guide_Run_Open' => 'Öppna {path} (denna sida) och stanna på fliken {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: klicka eller dra det nedladdade paketet till uppladdningsrutan. Stora filer laddas upp i små delar, så detta fungerar även på delade webbhotell med låga uppladdningsgränser. En kontrollsumma skyddar mot skadade eller ofullständiga uppladdningar.',
'Upd_Upload_The_Zip' => 'Ladda upp ZIP-filen',
'Upd_Guide_Run_Validation' => '{auto} efter uppladdningen (du kan köra den igen med knappen {button}). Systemet kontrollerar: ZIP-integritet, paketstruktur och fullständighet, versionskompatibilitet (nedgraderingar nekas), krävd PHP-version och tillägg, filbehörigheter, ledigt diskutrymme, databasanslutning, konfiguration samt att ingen annan uppdatering körs.',
'Upd_Validation_Runs_Automatically' => 'Validering körs automatiskt',
'Upd_Guide_Run_Review' => 'Granska panelen {panel}. Knappen {button} visas endast när alla kritiska kontroller godkänts. Om en kontroll misslyckas talar meddelandet om exakt vad som ska åtgärdas.',
'Upd_Guide_Run_Click' => 'Klicka på {button} och bekräfta. Sedan ska du bara {keep} och följa förloppet. Systemet utför, i ordning:',
'Upd_Keep_Page_Open' => 'hålla denna sida öppen',
'Upd_Guide_Phase_Backup' => '{label} — en fullständig databasdump, en ZIP av alla applikationsfiler som uppdateringen kan ändra och en kopia av {env} skapas och {verified}. Dina uppladdningar ({images}) och {storage} rörs aldrig av en uppdatering, så de arkiveras inte. Om en säkerhetskopia inte kan skapas stoppas uppdateringen här och inget ändras.',
'Upd_Verified' => 'verifieras',
'Upd_Guide_Phase_Prepare' => '{label} — den nya versionen packas upp i ett mellanlagringsområde och valideras igen. Den aktiva applikationen är fortfarande orörd.',
'Upd_Guide_Phase_Maintenance' => '{label} — underhållsläget aktiveras; besökare ser en vänlig skärm med "Vi är strax tillbaka".',
'Upd_Guide_Phase_Files' => '{label} — de nya filerna växlas in nästan omedelbart; de gamla filerna sparas undan för återställning. Skyddade sökvägar ({env}, {storage}, {images}) ersätts aldrig.',
'Upd_Guide_Phase_Database' => '{label} — migreringar körs, sedan uppdateras behörigheter, översättningar och mallar.',
'Upd_Guide_Phase_Cache' => '{label} — alla cacher töms och byggs om.',
'Upd_Guide_Phase_Verify' => '{label} — hälsokontroller bekräftar att den nya versionen startar, att databasen fungerar, att alla migreringar körts och att konfigurationen är giltig.',
'Upd_Guide_Phase_Done' => '{label} — underhållsläget avslutas och temporära filer rensas.',
'Upd_Guide_Run_Success' => 'När du ser {success}, klicka på {reload} och gör en hård uppdatering av webbläsaren ({keys}) så att de nya resurserna för adminpanelen laddas.',
'Upd_Update_Successful_Short' => 'Uppdateringen lyckades',
'Upd_Guide_No_Internet' => 'Ingen internetanslutning behövs under uppdateringen — allt kommer från den uppladdade ZIP-filen. Att tappa anslutningen eller stänga webbläsaren bryter INTE uppdateringen: servern kommer ihåg exakt var den stannade.',
'Upd_Guide_Wrong_Title' => '3. Om något går fel',
'Upd_Guide_Wrong_Rollback' => '{label} — om något misslyckas efter att filer börjat ändras (uppackningsfel, migreringsfel, misslyckad hälsokontroll, full disk, …) återställer systemet automatiskt de tidigare filerna och databasen från den verifierade säkerhetskopian, avslutar underhållsläget och rapporterar {message}. Du hamnar exakt där du började.',
'Upd_Automatic_Rollback' => 'Automatisk återställning',
'Upd_Failed_Previous_Restored' => 'Uppdateringen misslyckades — föregående version återställd',
'Upd_Guide_Wrong_Interrupted' => '{label} (serveromstart, timeout, stängd webbläsare, strömavbrott) — när du öppnar denna sida igen erbjuder en röd banner två säkra val: {resume} (fortsätter från exakt det steg där den stannade) eller {rollback} (återställer föregående version från säkerhetskopian).',
'Upd_Interrupted_Update' => 'Avbruten uppdatering',
'Upd_Guide_Wrong_Unreachable' => '{label} — använd den fristående {console} på {path}. Den fungerar även medan webbplatsen är i underhållsläge eller när adminpanelens resurser är trasiga, och erbjuder samma åtgärder Fortsätt / Återställ. Det finns också en diskret länk "Administratörsåtkomst" längst ned på underhållsskärmen.',
'Upd_Admin_Unreachable' => 'Adminpanelen kan inte nås',
'Upd_Recovery_Console' => 'återställningskonsolen',
'Upd_Guide_Wrong_Locked_Out' => '{label} — medan en uppdatering körs visar denna sida en {link}. Spara den om du behöver komma in igen (till exempel efter att din session gått ut); den släpper dig förbi underhållsskärmen så att du kan logga in igen.',
'Upd_Locked_Out_Maintenance' => 'Utestängd av underhållsläget',
'Upd_Bypass_Link' => 'förbikopplingslänk',
'Upd_Guide_Wrong_Concurrent' => '{label} — de kommer att se {message} Endast en uppdatering kan köras åt gången.',
'Upd_Another_Admin_Updating' => 'En annan administratör försöker uppdatera samtidigt',
'Upd_Guide_Backups_Title' => '4. Säkerhetskopior och återställning',
'Upd_Guide_Backups_Created' => 'Varje uppdatering skapar en säkerhetskopia {before} något rörs: alla applikationsfiler som uppdateringen kan ersätta, en kopia av {env} och en fullständig databasdump. Uppladdningar och {storage} ändras aldrig av en uppdatering och ingår därför inte — håll egna säkerhetskopior av dem. Säkerhetskopior finns i {path} och är aldrig åtkomliga från webben.',
'Upd_Before' => 'innan',
'Upd_Guide_Backups_Panel' => 'Panelen {panel} på fliken {tab} listar dem med datum, version och storlek. Därifrån kan du {restore} valfri fullständig säkerhetskopia (filer + databas — en säkerhetskopia av den aktuella databasen tas först) eller {delete} gamla.',
'Upd_Restore_Verb' => 'återställa',
'Upd_Delete_Verb' => 'ta bort',
'Upd_Guide_Backups_Retention' => 'Använd {keep} för att välja hur många säkerhetskopior som behålls; äldre tas bort automatiskt efter varje lyckad uppdatering. Den enda återstående fullständiga säkerhetskopian kan aldrig tas bort — du har alltid en väg tillbaka.',
'Upd_Guide_Manual_Title' => '5. Manuell uppdatering (reservmetod)',
'Upd_Guide_Manual_Text' => 'Om du föredrar att uppdatera manuellt, eller om uppladdaren inte kan användas på din server, följ steg-för-steg-instruktionerna på fliken {tab} på denna sida.',
'Upd_Guide_Clear_Cache_First' => 'Om sidor ser trasiga eller tomma ut efter en uppdatering, töm först webbläsarens cache — det är nästan alltid orsaken.',
'Upd_Restore_Backup_Confirm' => 'Återställa denna säkerhetskopia? Aktuella filer och den aktuella databasen ersätts av säkerhetskopian. En säkerhetskopia av den aktuella databasen tas först. (v{version} — {date})',
'Woo_Guide_Lead' => 'Hur en WooCommerce-butik håller sig i takt med ERP-systemet. Cron-raderna nedan är byggda för denna server, så de kan kopieras direkt till den.',
'Woo_Guide_Ways_Note' => 'Till skillnad från Shopify skickar WooCommerce ingenting till ERP-systemet av sig själv — det finns ingen webhook-mottagare här, så allt som kommer {in} anländer enligt schemat. Endast lager som går {out} kan vara omedelbart.',
'Woo_In' => 'in',
'Woo_Out' => 'ut',
'Woo_Guide_Both_Ways_Title' => 'Båda riktningarna behöver detta först',
'Woo_Api_Keys' => 'API-nycklar',
'Woo_Guide_Api_Keys_Text' => '{path}, behörighet {perm}. Kopiera consumer key och secret till fliken {settings}, tillsammans med butikens URL — webbplatsens adress utan avslutande snedstreck, t.ex. {example}.',
'Woo_Credentials_Saved' => 'inloggningsuppgifter sparade',
'Woo_Not_Configured_Yet' => 'inte konfigurerat ännu',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress-applikationslösenord (valfritt)',
'Woo_Guide_Wp_App_Password_Text' => 'Används endast för produktbilder. WooCommerce-API:t flyttar produkter, lager, kategorier, varumärken, kunder och ordrar; WordPress-API:t är det som söker i mediebiblioteket och laddar upp en bild som inte redan finns där.',
'Woo_Guide_Wp_App_Password_Note' => 'Använd en WordPress-användare som kan hantera media, och skapa lösenordet under {path}. Lämna båda fälten tomma så synkroniseras ändå allt — endast bildbifogning hoppas över.',
'Woo_Guide_Pick_Way_Title' => 'Välj sedan hur den håller sig i takt',
'Woo_Right_Away' => 'Direkt',
'Woo_Stock_Live' => 'lager live',
'Woo_Stock_Not_Live' => 'lager inte live',
'Woo_Guide_Realtime_Lead' => 'Endast en riktning: lager och produkter som lämnar ERP-systemet. Ordrar och produktändringar gjorda i WooCommerce anländer fortfarande enligt schemat — se den andra fliken.',
'Woo_Push_Stock_On_Change' => 'Pusha lager så fort det ändras',
'Woo_Setting_People_Miss' => 'Det här är inställningen folk missar',
'Woo_Guide_Pos_Sale_Not_Reach' => 'En POS-försäljning {not} WooCommerce av sig själv. Om det är avstängt får butiken veta det först vid nästa lagersynkronisering — som standard en timme — och under det fönstret kan den sälja en enhet som du redan har sålt i kassan.',
'Woo_Does_Not' => 'når inte',
'Woo_Guide_Tick_Instant' => 'Kryssa i {option} på fliken {settings}. Det är hela konfigurationen — ingen worker, ingen cron. Varje försäljning, retur, justering, överföring och mottaget inköp skickar då en push av just de produkterna, direkt efter att försäljningen sparats, och en försäljning med tjugo rader kostar en push, inte tjugo. Kassan väntar aldrig på det.',
'Woo_Currently' => 'För närvarande:',
'Woo_Instant_On_Text' => 'på — lager pushas vid ändring',
'Woo_Instant_Off_Text' => 'av — lager endast enligt schema',
'Woo_Guide_Instant_Note' => 'Endast produkter som redan är kopplade till WooCommerce pushas — en som aldrig har synkroniserats har inget i butiken att korrigera. Variabla produkter går via sin förälder, och en kombo pushas igen när någon av dess komponenter ändras. Massåtgärder (ta bort en produkt, återställa ett lager) skriver lager utan att utlösa en händelse, vilket är ett skäl att också behålla den timvisa lagersynkroniseringen.',
'Woo_Push_Products_On_Save' => 'Pusha produkter så fort de sparas',
'Woo_Guide_Tick_Auto_Products' => 'Kryssa i {option} på fliken {settings} så skickas en produkt som skapas, redigeras eller dupliceras i Stocky till WooCommerce direkt efter att den sparats — uppgifter, pris, varianter och bilder, sedan dess lager. En ny produkt skapas i butiken direkt i stället för att vänta på den nattliga produktsynkroniseringen.',
'Woo_On' => 'på',
'Woo_Off' => 'av',
'Woo_Guide_Bulk_Imports_Note' => 'Massimporter pushas inte en och en — kör en produktsynkronisering efter en import. Synkronisera kategorier och varumärken först, så att en pushad produkt hamnar i rätt kategori.',
'Woo_Nothing_Else_To_Install' => 'Inget mer att installera',
'Woo_Guide_Same_Process' => 'Ingen köworker, ingen cron-post. Pushen körs i samma process som hanterade försäljningen, {after} att svaret har skickats tillbaka, så kassan väntar aldrig på WooCommerce. Pushar överlappar aldrig: ändringar som görs medan en körs väntar på den och skickas direkt efteråt.',
'Woo_After' => 'efter',
'Woo_Guide_Shop_Stops_Answering' => 'En butik som slutar svara ges upp efter åtta sekunder, och pushar pausas i fem minuter så att inte varje försäljning väntar på den igen; ändringarna som kom in under tiden skickas med den första pushen efter pausen, och den timvisa lagersynkroniseringen kommer ikapp oavsett. Varje paus registreras på fliken Loggar.',
'Woo_Guide_Artisan_Exception' => 'Ett undantag: en lagerändring gjord av ett artisan-kommando har inget svar att komma efter, så den köas i stället på {queue}. För att även få dem skickade snabbt, töm den kön:',
'Woo_Cron_Line_Copied' => 'Cron-rad kopierad',
'Woo_Command_Copied' => 'Kommando kopierat',
'Woo_Guide_Not_Woo_Queue' => 'Avsiktligt inte kön {queue}: den bär de timslånga katalogbatcherna, och en omedelbar push som köas bakom en sådan skulle inte vara omedelbar.',
'Woo_On_A_Schedule' => 'Enligt schema',
'Woo_Guide_Scheduled_Lead' => 'Allt kontrolleras om med jämna mellanrum, i båda riktningarna. Det är så ordrar når ERP-systemet, hur en katalog publiceras och vad som reparerar allt som den snabba vägen missade. Varje jobb får sin egen cron-post, så du kör bara det du vill.',
'Woo_Guide_Sync_Drains_Queue' => '{command} tömmer sin egen kö medan den körs, så dessa rader behöver ingen separat worker. På Windows, använd Schemaläggaren med programmet {program} och samma argument, startat i {path}.',
'Woo_Or_No_Cron' => 'Eller ingen cron alls',
'Woo_Guide_No_Cron_Text' => 'Varje flik här synkroniserar på begäran, och en manuell synkronisering tömmer sina egna batcher medan sidan är öppen — så en liten butik kan köras helt utan cron-post. Det du förlorar är allt som händer när ingen tittar: ordrar anländer bara när någon trycker på knappen.',
'Woo_Commands_Worth_Knowing' => 'Kommandon värda att känna till',
'Woo_Worth_Knowing' => 'Värt att veta',
'Woo_Guide_Changing_Url_Clears' => 'Att ändra butikens URL eller API-nycklarna rensar alla kopplingar — produkter, kategorier, varumärken och kunder synkroniseras alla på nytt till den nya butiken.',
'Woo_Guide_Keep_Skus' => 'Håll SKU:er konsekventa mellan Stocky och WooCommerce: det är det som förhindrar dubbletter och gör omkoppling säker.',
'Woo_Guide_Stock_Total' => 'Lager som publiceras till Woo är {total}, inte ett enskilt lagers siffra.',
'Woo_Total_Across_Warehouses' => 'summan över alla lager',
'Woo_Guide_Full_Reference' => 'Den fullständiga referensen — varje omfång, hur kön beter sig och en felsökningslista — finns i {file}.',
'Woo_Way_Covers' => 'Omfattar',
'Woo_Way_Covers_Realtime' => 'Endast lager som lämnar ERP-systemet — en POS-försäljning, en retur, en justering, ett mottaget inköp',
'Woo_Way_Covers_Scheduled' => 'Allt, i båda riktningarna: ordrar och produktändringar in, katalog och lager ut',
'Woo_Way_Speed' => 'Hastighet',
