'Woo_Way_Speed_Scheduled' => 'Det du anger i cron-posten (lager varje timme, ordrar var 15:e minut)',
'Woo_Way_Needs' => 'Kräver',
'Woo_Way_Needs_Realtime' => 'Ingenting — bara inställningen',
'Woo_Way_Needs_Scheduled' => 'En cron-post per jobb — eller ingenting, om du synkroniserar manuellt',
