'Woo_Cmd_Pull' => 'Allt inkommande på en gång: produkter, ordrar, kunder.',
'Woo_Guide_Page_Title' => 'WooCommerce-guide',
'Woo_Guide_Page_Subtitle' => 'Ansluta butiken, vad som körs av sig självt och cron-posterna för denna server',
'Woo_Settings_Button' => 'WooCommerce-inställningar',
'Woo_No_Shop_Connected' => 'Ingen butik är ansluten ännu',
'Woo_No_Shop_Connected_Desc' => 'Allt nedan gäller fortfarande — ange butikens URL och API-nycklar på sidan WooCommerce-inställningar och kom sedan tillbaka.',
'Woo_Wp_Username' => 'WordPress-användarnamn',
'Woo_Wp_App_Password' => 'WordPress-applikationslösenord',
'Woo_Settings_Instant_Hint' => 'En försäljning, retur eller justering skickar en lagerpush för just de produkterna i samma ögonblick som den sparas, så butiken är korrekt inom några sekunder i stället för vid nästa timvisa lagersynkronisering. Inget mer att installera — pushen körs efter att försäljningen har besvarats, så kassan väntar aldrig på WooCommerce. Mer på fliken {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Lämna det avstängt så når en POS-försäljning WooCommerce först vid nästa lagersynkronisering — upp till en timme senare.',
'Woo_Settings_Auto_Products_Hint' => 'En produkt som skapas, redigeras eller dupliceras i Stocky skickas till WooCommerce direkt efter att den sparats — uppgifter, pris, varianter, bilder, sedan dess lager — i stället för att vänta på en produktsynkronisering. Massimporter pushas inte; kör en produktsynkronisering efter en import.',
'Woo_Sync_Tuning' => 'Finjustering av synkronisering',
'Woo_Sync_Tuning_Intro' => 'Standardvärdena passar de flesta butiker. Ändra dessa endast om synkroniseringen är långsam eller får timeout på ditt webbhotell. Varje värde begränsas till ett säkert intervall, och att tömma ett fält återställer dess standardvärde.',
'Woo_Setting_This_Up' => 'Konfigurera detta',
'Woo_Setting_This_Up_Text' => 'Att skaffa API-nycklarna, vad WordPress-applikationslösenordet är till för, cron-posterna för schemalagda synkroniseringar och hur du får lagret att nå butiken så fort det ändras — allt detta, med denna servers egna cron-rader redo att kopiera, finns på fliken Guide. En enda kopia, så den kan inte glida isär från vad modulen faktiskt gör.',
