'Shopify_G_Lead_Store' => 'Vad denna butik behöver för att hålla sig i takt. Allt här är specifikt för denna butik — sökvägarna och id:na är verkliga, så kommandona kan kopieras direkt till servern.',
'Shopify_G_Lead_Generic' => 'Hur en Shopify-butik håller sig i takt med ERP-systemet. Välj en butik ovan för att se dess eget tillstånd, eller läs det som det är — cron-raden och webhook-URL:en är desamma oavsett vilken butik du ansluter.',
'Shopify_G_Ways_Note' => 'De flesta butiker kör båda: den första håller butiken aktuell minut för minut, den andra fångar det som den första missade — en webhook som aldrig kom fram, en ändring gjord direkt i Shopify admin, en natt när webbplatsen var nere.',
'Shopify_G_Both_Need' => 'Båda riktningarna behöver detta först',
'Shopify_G_Credentials' => 'Shopify-inloggningsuppgifter',
'Shopify_G_Cred_Intro' => 'Sedan januari 2026 skapar Shopify inte längre anpassade appar i admin, så det finns två typer av anslutning:',
'Shopify_G_Cred_DevDash' => '{app} (alla butiker som ansluts nu) — {path}. Ge Admin API-scopes för det som denna butik synkroniserar, installera appen i butiken och kopiera sedan {clientId} och {clientSecret} från appens inställningssida till {where}. ERP-systemet byter själv ut dem mot en åtkomsttoken och förnyar den innan den går ut var 24:e timme. Client secret signerar även webhooks, så inget annat behövs. Appen och butiken måste finnas i samma Shopify-organisation.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard-app',
'Shopify_G_Cred_Legacy' => '{app} (skapad i admin före 2026) — fortsätter att fungera oförändrad med sin {token} ({prefix}) och sin {secret} som signeringssecret för webhooks. Inte samma värde som token, och att blanda ihop dem är den vanliga orsaken till att webhooks nekas.',
'Shopify_G_Legacy_App' => 'Äldre anpassad app',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'lagrad',
'Shopify_G_Missing_Refused' => 'saknas — leveranser kommer att nekas',
'Shopify_G_Where_Data_Desc' => '{path} ERP-lagret vars lager denna butik säljer, och Shopify-platsen som lagret skrivs till. Lagersynkronisering och orderimport vägrar båda att köras utan dem.',
'Shopify_G_Currently' => 'För närvarande: lager {warehouse}, plats {location}',
'Shopify_G_Not_Set_Lower' => 'ej angivet',
'Shopify_G_Ready' => 'redo',
'Shopify_G_Incomplete' => 'ofullständig',
'Shopify_G_Manual_Syncs' => 'Synkroniseringar du startar manuellt',
'Shopify_G_Manual_Desc' => 'En synkronisering som startas från {centre} svarar direkt och körs i bakgrunden, i korta delar som var och en fortsätter där den förra slutade. En stor katalog avbryts aldrig halvvägs av webbhotell som avslutar långa webbförfrågningar (LiteSpeed, nginx, en lastbalanserare), och att stänga sidan stoppar den inte. Workern för detta är ytterligare en cron-rad:',
'Shopify_G_Cron_Copied' => 'Cron-rad kopierad',
'Shopify_G_Manual_Note' => 'Utan den slutförs en synkronisering ändå, men bara medan sidan Synkroniseringscenter är öppen: när ingen worker plockar upp en körning inom några sekunder fortsätter sidan med den själv, en kort förfrågan åt gången. På Windows, använd Schemaläggaren varje minut: programmet {program}, argumenten {args}, startat i {dir}.',
'Shopify_G_Then_Pick' => 'Välj sedan hur den håller sig i takt',
'Shopify_G_Right_Away' => 'Direkt',
'Shopify_G_Stock_Live' => 'lager live',
'Shopify_G_Stock_Not_Live' => 'lager inte live',
'Shopify_G_Realtime_Lead' => 'Varje ändring skickas när den sker, på några sekunder. Två halvor, och de är separata reglage: {webhooks} tar in butikens egna händelser, och {push} skickar ut lager.',
'Shopify_G_Webhooks_Lower' => 'webhooks',
'Shopify_G_Instant_Push_Lower' => 'omedelbar lagerpush',
'Shopify_G_Webhooks_In' => 'Webhooks — butiken → ERP-systemet',
'Shopify_G_Webhooks_Desc' => 'Ordrar, orderstatusändringar samt produkt-, kund- och lagerändringar gjorda i Shopify. Öppna butiken och tryck på {button} på dess {tab} — säkert att trycka två gånger. Shopify skickar till:',
'Shopify_G_Webhooks_Tab' => 'flik Webhooks',
'Shopify_G_Webhooks_Note' => 'Adressen måste vara nåbar från internet över HTTPS — Shopify levererar inte till {localhost} eller en {test}-domän. Varje leverans registreras en gång, så Shopifys omförsök kan inte skapa en dubblettorder, och en misslyckad kan spelas upp igen. Leveranser nekas tills signeringssecret från steg 1 är lagrad.',
'Shopify_G_Instant_Out' => 'Omedelbar lagerpush — ERP-systemet → butiken',
'Shopify_G_Setting_Missed' => 'Det här är inställningen folk missar',
'Shopify_G_Pos_Not_Auto' => 'En POS-försäljning når {not} Shopify av sig själv. Om det är avstängt får butiken veta det först vid nästa steg för lagerpush — och under det fönstret kan den sälja en enhet som du redan har sålt i kassan.',
'Shopify_G_Not' => 'inte',
'Shopify_G_Tick_Push' => 'Kryssa i {setting} under {where}. Det är hela konfigurationen — ingen worker, ingen cron. Varje försäljning, retur och justering skickar då en push av just de produkterna, direkt efter att försäljningen sparats, och en försäljning med tjugo rader kostar en push, inte tjugo. Kassan väntar aldrig på det.',
'Shopify_G_This_Store' => 'Denna butik:',
'Shopify_G_Push_On' => 'på — lager pushas vid ändring',
'Shopify_G_Push_Off' => 'av — lager endast enligt schema',
'Shopify_G_Push_Note' => 'Endast produkter som redan har en Shopify-koppling, och endast rörelser i denna butiks lager, pushas. Massåtgärder — ta bort en produkt, återställa ett lager — skriver lager utan att utlösa en händelse, vilket är ett skäl att också behålla det schemalagda lagersteget.',
'Shopify_G_Nothing_Install' => 'Inget mer att installera',
'Shopify_G_No_Worker_Note' => 'Ingen av halvorna behöver en köworker eller en cron-post. En inkommande webhook hanteras i den förfrågan som Shopify gör; en utgående lagerpush körs i samma process som hanterade försäljningen, {after} att svaret har skickats tillbaka — så kassan väntar aldrig på Shopify, och en butik som slutar svara ges upp efter tio sekunder och lämnas till nästa schemalagda lagerpush.',
'Shopify_G_After' => 'efter',
'Shopify_G_Artisan_Note' => 'Ett undantag: en lagerändring gjord av ett artisan-kommando har inget svar att komma efter, så den köas i stället på {queue}. Om du vill att även de ska skickas snabbt, töm den kön:',
'Shopify_G_On_Schedule' => 'Enligt schema',
'Shopify_G_On_Lower' => 'på',
'Shopify_G_Off_Lower' => 'av',
'Shopify_G_Scheduled_Lead' => 'Allt kontrolleras om med jämna mellanrum, i båda riktningarna. Långsammare än realtid, men det är det som pushar ut lager i butiker som inte använder omedelbar push, det som fångar en missad webhook och det enda sättet att flytta en hel katalog.',
'Shopify_G_Cron_Entry' => 'Cron-posten',
'Shopify_G_Cron_Entry_Desc' => 'Inget schemalagt körs utan den. En rad, endast för denna modul — lägg till den bredvid det du annars har valt att schemalägga:',
'Shopify_G_Cron_Note' => 'Var femte minut är den finaste upplösningen en plan kan använda, eftersom fem minuter är det kortaste stegintervallet. En grövre post blir helt enkelt golvet — med {example} körs ett steg inställt på 5 minuter var 15:e. På Windows, använd Schemaläggaren: programmet {program}, argumenten {args}, startat i {dir}.',
'Shopify_G_Switch_On_Plan' => 'Slå på det och välj plan',
'Shopify_G_Plan_Desc' => '{where} Reglaget avgör om cron får agera över huvud taget; planen avgör vad den gör. Ett {step} är en entitet i en riktning med sitt eget intervall — {first}, {second}. Standardintervallet används av alla steg som lämnar sin egen ruta tom.',
'Shopify_G_Step_Lower' => 'steg',
'Shopify_G_Plan_Note' => 'Lämna planen tom så hämtar butiken ordrar och pushar lager med standardintervallet, vilket är vad de flesta butiker vill. Ordrar hämtas endast: Shopify är där en kund lägger en.',
'Shopify_G_Schedule_On' => 'schema på',
